<template>
  <view class="detail-page">
    <SiteHeader active="intelligence" />
    <view class="detail-shell">
      <view class="back" role="link" tabindex="0" @click="goBack" @keydown.enter.prevent="goBack">← 返回案例库</view>
      <view v-if="article" class="article-layout">
        <view class="main-column">
          <view class="article-header">
            <view v-if="study" class="case-tags"><text>{{study.direction}}</text><text v-for="tag in study.startTags" :key="tag">{{tag}}</text><text class="verified-tag">完整解读</text></view>
            <view v-else class="source-label">● 来源：生财有术 <text>{{ article.isDigested ? '精华文章' : '圈友分享' }}</text></view>
            <view class="headline">{{ cleanCaseTitle(article.title) }}</view>
            <view class="byline">{{ study?.author || '一位生财圈友' }}（本站隐去昵称） · 来源：生财有术 · {{ formatDate(article.publishedAt) }} <text v-if="study" class="inline-source" @click="openSource">查看原帖 ↗</text></view>
            <button v-if="study && study.simulation" class="case-play-top" @click="openSimulation"><text>▶ 先玩一局同款模拟</text><text>开始 →</text></button>
          </view>
          <template v-if="study">
            <view class="case-overview"><view class="case-lead"><view class="lead-label">一句话看懂</view><view class="lead-body">{{study.oneLiner}}</view></view><view class="number-grid"><view v-for="n in study.numbers" :key="n.label" class="number-card" :class="{'undisclosed':!n.value}"><text class="number-label">{{n.label}}</text><text class="number-value">{{n.value || '未披露'}}</text><text class="number-note">{{n.note}}</text></view></view></view>
            <view class="case-block"><view class="case-heading"><text>1</text>这是什么项目</view><view class="fact-card"><view v-for="row in projectRows" :key="row[0]" class="fact-row"><text>{{row[0]}}</text><text>{{row[1] || '未披露'}}</text></view></view></view>
            <view class="case-block"><view class="case-heading"><text>2</text>作者从什么条件开始</view><view class="fact-card"><view v-for="row in startRows" :key="row[0]" class="fact-row"><text>{{row[0]}}</text><text :class="{'not-disclosed':!row[1]}">{{row[1] || '未披露'}}</text></view></view></view>
            <view id="case-steps" class="case-block"><view class="case-heading"><text>3</text>具体怎么做</view><view class="case-timeline"><view v-for="step in study.steps" :key="step.title" class="case-step"><view><text class="case-step-title">{{step.title}}</text><text class="case-step-detail">{{step.detail}}</text></view></view></view></view>
            <view class="case-block"><view class="case-heading"><text>4</text>结果与踩坑</view><view class="fact-card result-card"><view v-for="n in study.numbers.filter(n=>n.value)" :key="n.label" class="fact-row"><text>{{n.label}}</text><text>{{n.value}} · {{n.note}}</text></view></view><view v-for="(pit,pitIndex) in study.pitfalls" :key="pit.title" class="pitfall"><text class="case-step-title">坑：{{pit.title}}</text><text class="case-step-detail">{{pit.detail}}</text><button v-if="hasPitDecision(study.id,pitIndex)" class="pit-play" @click="openSimulation">模拟里也有类似决策，试一试 →</button></view></view>
            <view class="case-block"><view class="case-heading"><text>5</text>适合谁、开始前要想什么</view><view class="judge-card"><text class="judge-label">站方判断 · 不是原帖内容</text><view class="judge-title">可能适合</view><view v-for="(line,i) in study.judgement.fitFor" :key="'fit'+i" class="judgement-line">• {{line}}</view><view class="judge-title">开始前想清楚</view><view v-for="(line,i) in study.judgement.thinkFirst" :key="'think'+i" class="judgement-line">• {{line}}</view></view></view>
          </template>
          <view v-else class="intro-card"><view class="intro-label">AINPE 案例导读 <text>基于已收录资料整理</text></view><template v-if="expandedSummary"><view class="intro-title">这篇内容讲了什么</view><view class="intro-body">{{ expandedSummary.what }}</view><view class="intro-title">做法与观察</view><view class="intro-body">{{ expandedSummary.how }}</view><view class="intro-title">阅读时需要注意</view><view class="intro-body">{{ expandedSummary.note }}</view></template><template v-else><view class="intro-title">短摘要 · 资料不足</view><view class="intro-body">{{ displaySummary }}</view></template><view class="intro-note">这是导读，完整内容以原帖为准。</view></view>
          <view v-if="isAiArticle(article)" :class="['practice', {'study-practice':study}]"><view class="practice-title">{{matchingGame ? `读完，亲手试一次：${matchingGame.name}` : '先体验一个 AI 项目'}}</view><button class="play-action" @click="openSimulation">{{matchingGame ? '玩相关模拟 →' : '查看模拟项目 →'}}</button></view>
          <view v-if="article.sourceUrl" class="src-block"><text class="src-q">{{study ? '想看作者的完整原帖？' : '想看完整原文？'}}</text><view class="src-btns"><view class="src-a" @click="openReferral">加入生财，看完整原帖</view><view class="src-m" @click="openSource">查看原帖</view></view></view>
          <view v-if="isProjectArticle && !(study && matchingGame)" class="reservation"><view class="section-heading">想体验这篇文章中的项目？</view><button class="reserve-button" :disabled="reserveLoading || reserved || !reservationAvailable" @click="reserve">{{ reserved ? '已预约体验' : reserveLoading ? '正在记录…' : '预约体验这个项目' }}</button><view class="reserve-meta">{{ reservationAvailable ? (reservationCount >= 10 ? `已有 ${reservationCount} 条预约记录。` : '想体验的人多了，我们会优先考虑。') + ' 同一浏览器仅计一次，不收联系方式，也不会自动通知。' : '预约统计暂不可用，请稍后再试。' }}</view></view>
          <view v-else-if="isEventArticle" class="reservation"><view class="section-heading">想了解线下活动？</view><button class="reserve-button" @click="openEvents">查看线下活动</button></view>
          <view class="actions"><button class="save" @click="toggleSaved">{{ saved ? '★ 已收藏' : '☆ 收藏' }}</button></view>

          <view v-if="related.length" class="related"><view class="section-heading">接着看看相关案例</view><view v-for="item in related" :key="item.id" class="related-row" @click="openArticle(item)"><view><text class="related-title">{{ item.title }}</text><text class="related-meta">一位生财圈友 · {{ item.kind || '分享' }}</text></view><text class="related-arrow">↗</text></view></view>
          <view class="footnote">{{study ? '站方解读，数字为作者自述。' : '内容以原帖为准。'}}</view>
        </view>
        <view class="side-column"><view class="side-card"><view class="side-eyebrow">读完，亲手试一次</view><view class="side-title">{{matchingGame ? matchingGame.name : '找到适合自己的方向'}}</view><view class="side-copy">过程和金额均为模拟。</view><button class="side-action" @click="openSimulation">{{matchingGame ? '体验这个项目 →' : '看看模拟项目 →'}}</button></view><view v-if="related.length" class="side-related"><view class="side-related-title">其他方向的案例</view><view v-for="item in related" :key="item.id" class="side-related-item" @click="openArticle(item)">{{item.title}}<text>{{caseById(item.id)?.author || '一位生财圈友'}} · 生财有术</text></view></view></view>
      </view>
      <view v-else-if="feedMeta.loading || !feedMeta.loadAttempted" class="not-found"><view>正在加载文章…</view><text>请稍候。</text></view>
      <view v-else-if="feedMeta.loadFailed" class="not-found"><view>暂时无法加载文章</view><text>请检查网络连接后重试。</text><button @click="refreshFeed">重新加载</button></view>
      <view v-else class="not-found"><view>暂未找到这篇文章</view><text>它可能不在当前已收录的资料中。</text><button @click="goBack">返回文章列表</button></view>
    </view>
    <view v-if="false" class="case-play-sticky"><view><text>{{study.simulation.name}} · 模拟</text><text>读到这里，亲手试一次</text></view><button @click="openSimulation">玩相关模拟 ▶</button><button class="case-play-close" aria-label="关闭模拟推荐" @click="dismissPlayBar=true">×</button></view>
  <SiteFooter /></view>
</template>

<script setup>
import SiteFooter from '../../components/SiteFooter.vue';
import {computed, ref, watch, onMounted, onUnmounted, getCurrentInstance} from 'vue';
import {onLoad, onShow, onPageScroll} from '@dcloudio/uni-app';
import {articles, isAiArticle, feedMeta, refreshFeed} from '../../data/content.js';
import summaries from '../../data/article-summaries.json';
import SiteHeader from '../../components/SiteHeader.vue';
import {openExternal,REFERRAL_URL} from '../../data/offer.js';
import {track} from '../../data/track.js';
import {matchArticleGame,simulationUrl,openGame} from '../../data/game-matching.js';
import {caseStudies,caseById,caseAsArticle} from '../../data/case-studies.js';
import {isCaseLibraryItem,cleanCaseTitle,shortCaseSummary,relatedReviewedCases} from '../../data/case-library.mjs';

// Each linked pit has a corresponding decision in the named, reviewed simulation.
const linkedPitDecisions={'82258452211188182':[0],'22258221581184141':[1],'14588481121824442':[0,1],'45544522454884258':[0,2],'45548881815182188':[0]};
function hasPitDecision(caseId,index){return (linkedPitDecisions[String(caseId)]||[]).includes(index)}
const id=ref(''), showPlayBar=ref(false), dismissPlayBar=ref(false);
const pageInstance=getCurrentInstance();
let playBarTimer;
function updatePlayBar(){
  if(!study.value?.simulation){showPlayBar.value=false;return;}
  // #ifdef H5
  const section=document.getElementById('case-steps');
  showPlayBar.value=!!section&&section.getBoundingClientRect().bottom<90;
  // #endif
  // #ifndef H5
  uni.createSelectorQuery().in(pageInstance.proxy).select('#case-steps').boundingClientRect(rect=>{showPlayBar.value=!!rect&&rect.bottom<90;}).exec();
  // #endif
}
onPageScroll(()=>{clearTimeout(playBarTimer);playBarTimer=setTimeout(updatePlayBar,80);});
onUnmounted(()=>clearTimeout(playBarTimer));
const savedIds=ref([]);
const study=computed(()=>caseById(id.value));
const article=computed(()=>study.value ? caseAsArticle(study.value) : (Array.isArray(articles)?articles:[]).find(item=>String(item.id)===id.value));
const projectRows=computed(()=>study.value ? [['项目',study.value.project.what],['面向谁',study.value.project.audience],['怎样获客',study.value.project.acquisition],['收入方式',study.value.project.revenueModel]] : []);
const startRows=computed(()=>study.value ? [['职业与状态',study.value.start.occupation],['相关经验',study.value.start.experience],['每天时间',study.value.start.dailyTime],['启动预算',study.value.start.budget]] : []);
const storageKey=computed(()=>`article:${id.value}`);
const saved=computed(()=>savedIds.value.includes(storageKey.value));
const expandedSummary=computed(()=>summaries[id.value]||null);
const displaySummary=computed(()=>shortCaseSummary(article.value?.overview||article.value?.summary));
const matchingGame=computed(()=>study.value ? study.value.simulation : matchArticleGame(article.value));
const isEventArticle=computed(()=>/(线下|聚会|组局|大会|沙龙|夜话)/i.test(String(article.value?.title||'')));
const isProjectArticle=computed(()=>!!article.value && isAiArticle(article.value) && !isEventArticle.value && (article.value.kind==='案例'||/(项目|副业|变现|获客|带货|接单|营收|收入|小程序|工具|工作流|智能体|开发|搭建|视频制作|创作)/i.test(`${article.value.title||''} ${article.value.summary||''}`)));
const reserveLoading=ref(false), reserved=ref(false), reservationCount=ref(0), reservationAvailable=ref(false);
let reservationEnabled=false;
// #ifdef H5
reservationEnabled=true;
// #endif
function api(options){return new Promise((resolve,reject)=>uni.request({...options,timeout:8000,success:r=>r.statusCode>=200&&r.statusCode<300?resolve(r.data):reject(new Error('unavailable')),fail:reject}));}
async function loadReservation(){reservationAvailable.value=false;reserved.value=false;reservationCount.value=0;if(!reservationEnabled||!/^\d{1,30}$/.test(id.value))return;const current=id.value;try{const d=await api({url:'/api/reservations',method:'GET'});const key=`article:${current}`;if(!d||d.countUnit!=='browser'||!Array.isArray(d.mine)||!d.counts||typeof d.counts!=='object')throw Error();const count=d.counts[key]??0;if(!Number.isInteger(count)||count<0)throw Error();if(id.value!==current)return;reservationCount.value=count;reserved.value=d.mine.includes(key);reservationAvailable.value=true;}catch{reservationAvailable.value=false;}}
async function reserve(){if(!reservationAvailable.value||reserveLoading.value||reserved.value)return;reserveLoading.value=true;const current=id.value;try{const key=`article:${current}`;const d=await api({url:'/api/reservations',method:'POST',header:{'Content-Type':'application/json'},data:{projectId:key}});if(d?.projectId!==key||d.reserved!==true||d.countUnit!=='browser'||!Number.isInteger(d.count)||d.count<0)throw Error();if(id.value!==current)return;reservationCount.value=d.count;reserved.value=true;}catch{reservationAvailable.value=false;uni.showToast({title:'预约未完成，请稍后再试',icon:'none'});}finally{reserveLoading.value=false;}}
const related=computed(()=>{
  if(!article.value)return [];
  if(study.value)return relatedReviewedCases(study.value,caseStudies).map(caseAsArticle);
  const topics=new Set((Array.isArray(article.value.topics)?article.value.topics:[]).filter(topic=>topic!=='community'));
  if(!topics.size)return [];
  return (Array.isArray(articles)?articles:[]).filter(item=>String(item.id)!==id.value&&isCaseLibraryItem(item)&&(item.topics||[]).some(topic=>topics.has(topic))).slice(0,3);
});
watch(()=>article.value?.title,title=>{if(title)uni.setNavigationBarTitle({title:cleanCaseTitle(title)});},{immediate:true});
function loadLocal(){try{const ids=uni.getStorageSync('ainpe:saved');savedIds.value=Array.isArray(ids)?ids:[];}catch{savedIds.value=[];}}
onLoad(options=>{id.value=String(options?.id||'');loadLocal();loadReservation();});
onShow(()=>{if(id.value){loadLocal();loadReservation();if(article.value?.title)uni.setNavigationBarTitle({title:cleanCaseTitle(article.value.title)});}});
// #ifdef H5
function syncArticleFromHash(){const hash=window.location.hash;const q=hash.indexOf('?');if(q<0||hash.slice(0,q)!=='#/pages/article/index')return;const next=new URLSearchParams(hash.slice(q+1)).get('id')||'';if(next!==id.value){id.value=next;showPlayBar.value=false;dismissPlayBar.value=false;loadLocal();if(next)loadReservation();}}
onMounted(()=>{window.addEventListener('hashchange',syncArticleFromHash);window.addEventListener('scroll',updatePlayBar,true)});
onUnmounted(()=>{window.removeEventListener('hashchange',syncArticleFromHash);window.removeEventListener('scroll',updatePlayBar,true)});
// #endif
function toggleSaved(){const next=saved.value?savedIds.value.filter(key=>key!==storageKey.value):[...savedIds.value,storageKey.value];try{uni.setStorageSync('ainpe:saved',next);savedIds.value=next;uni.showToast({title:saved.value?'已收藏':'已取消收藏',icon:'none'});}catch{uni.showToast({title:'保存失败，请检查存储空间',icon:'none'});}}
function goBack(){uni.redirectTo({url:'/pages/intelligence/index'});}
function openEvents(){uni.navigateTo({url:'/pages/events/index'});}
function openSimulation(){
if(study.value?.simulation?.url){const url=study.value.simulation.url;uni.navigateTo({url:url+(url.includes('?')?'&':'?')+'from='+encodeURIComponent('case:'+id.value)});return;}
if(matchingGame.value){let url=simulationUrl(matchingGame.value.file);if(url){url+=(url.includes('?')?'&':'?')+'from='+encodeURIComponent('case:'+id.value);if(openGame(url))return;}}
uni.navigateTo({url:'/pages/simulate/index'});
}
function openSource(){const source=String(article.value?.sourceUrl||'');if(!/^https:\/\/(?:www\.)?scys\.com\//i.test(source))return;uni.navigateTo({url:'/pages/camp/index?from=article&source='+encodeURIComponent(source)});}
function openReferral(){track('outbound_click',{target:'referral',from:'article'});openExternal(REFERRAL_URL);}
function openArticle(item){try{uni.setStorageSync('ainpe:last-article',{id:String(item.id),openedAt:Date.now()});}catch{}uni.navigateTo({url:`/pages/article/index?id=${encodeURIComponent(String(item.id))}`});}
function formatDate(value){const d=new Date(Number(value)*1000+8*3600000);return Number.isNaN(d.getTime())?'时间待确认':`${d.getUTCFullYear()}年${d.getUTCMonth()+1}月${d.getUTCDate()}日`;}
</script>

<style scoped>
.side-illo{height:auto!important;padding:8px 8px 0;box-sizing:border-box;background:#0b2e20}.side-camp:has(.side-illo){background:#0b2e20}
.src-block{margin:6px 0 0}.src-q{display:block;font-size:15px;font-weight:900;color:#13241b;margin:0 2px 8px}.src-btns{display:flex;gap:8px}.src-btns view{flex:1;display:flex;min-height:44px;align-items:center;justify-content:center;border-radius:12px;font-size:14px;font-weight:900;cursor:pointer;text-align:center;padding:0 8px}.src-a{background:#0b2e20;color:#fff}.src-m{border:1.5px solid #e5decf;color:#45594d;background:#fff;flex:0 0 34%!important}
.detail-page{min-height:100vh;background:#f4f3ee;color:#1d3d2e}.detail-shell{max-width:1200px;margin:0 auto;padding:32rpx 28rpx 130rpx}.back{font-size:24rpx;color:#7b927b;margin:0 0 28rpx}.article-layout{display:flex;gap:28rpx}.main-column{flex:1;min-width:0}.side-column{display:none}.article-header{padding:24rpx 0 32rpx}.source-label{font-size:21rpx;color:#799966;font-weight:700}.source-label text{font-weight:400;color:#98a790;padding-left:12rpx}.headline{font-size:43rpx;font-weight:800;line-height:1.35;color:#1a3528;margin:20rpx 0}.byline{font-size:22rpx;color:#94a18f}.intro-card,.discussion,.personal,.related{background:#fff;border:1px solid #e0e8dd;border-radius:12rpx;padding:28rpx;margin-bottom:22rpx}.intro-label{font-size:20rpx;font-weight:750;color:#648b59}.intro-label text{font-size:19rpx;color:#9ba99a;font-weight:400;margin-left:14rpx}.intro-title,.section-heading{font-size:29rpx;font-weight:750;color:#244631;margin-top:18rpx}.intro-body{font-size:26rpx;line-height:1.85;color:#405a47;margin-top:16rpx;white-space:pre-wrap}.intro-note{border-top:1px solid #e9eee6;margin-top:24rpx;padding-top:18rpx;font-size:21rpx;line-height:1.65;color:#91a18c}.section-heading{margin-top:0}.section-heading text{font-size:20rpx;color:#94a78f;font-weight:400}.section-hint{font-size:21rpx;color:#93a191;line-height:1.6;margin-top:10rpx}.comment{border-top:1px solid #edf0eb;margin-top:22rpx;padding-top:20rpx}.comment-meta{display:flex;gap:14rpx;font-size:22rpx;color:#365c40;font-weight:700}.comment-angle{font-size:19rpx;color:#90a18c;font-weight:400}.comment-text{border-left:4rpx solid #cfe0c4;padding-left:18rpx;margin-top:12rpx;color:#617966;font-size:23rpx;line-height:1.75;white-space:pre-wrap}.notes{width:100%;box-sizing:border-box;margin-top:18rpx;padding:18rpx;background:#f7faf4;border:1px solid #dfeadb;border-radius:8rpx;font-size:24rpx;line-height:1.6;color:#2e4c36;height:160rpx}.personal-row{display:flex;align-items:center;gap:15rpx;font-size:22rpx;color:#7b9079;margin-top:18rpx;flex-wrap:wrap}.picker-value{padding:11rpx 20rpx;border:1px solid #dfe9d8;border-radius:7rpx;background:#f7faf4;color:#426a45}.personal-hint{margin-left:auto;color:#9da996;font-size:19rpx}.actions{display:flex;gap:14rpx;margin:22rpx 0}.actions button{margin:0;padding:0 23rpx;border-radius:8rpx;font-size:23rpx;line-height:68rpx}.actions button:after{border:0}.save{background:#fff;color:#446c49;border:1px solid #dce8d7}.source{background:#254d36;color:#fff}.camp{display:flex;align-items:center;gap:24rpx;padding:24rpx;background:#ecf4e8;border:1px solid #d7e8d0;border-radius:12rpx;margin:25rpx 0}.camp-image{width:110rpx;height:240rpx;flex-shrink:0}.camp-kicker,.related-label{font-size:19rpx;color:#7d9e70;font-weight:700;letter-spacing:1rpx}.camp-title{font-size:29rpx;font-weight:750;margin-top:8rpx}.camp-copy{font-size:21rpx;color:#7e917b;line-height:1.7;margin-top:8rpx}.camp-link{color:#34724a;font-size:23rpx;font-weight:700;margin-top:13rpx}.related{margin-top:28rpx}.related .section-heading{margin-top:8rpx}.related-row{display:flex;align-items:center;justify-content:space-between;gap:20rpx;border-top:1px solid #edf1e9;padding:20rpx 0}.related-row:first-of-type{margin-top:18rpx}.related-title,.related-meta{display:block}.related-title{font-size:24rpx;color:#2d4c38;line-height:1.5}.related-meta{font-size:19rpx;color:#9ca99b;margin-top:6rpx}.related-arrow{font-size:26rpx;color:#90a789}.footnote{font-size:19rpx;line-height:1.7;color:#9ba998;text-align:center;margin-top:35rpx}.not-found{padding:80rpx 20rpx;text-align:center;font-size:32rpx;font-weight:700}.not-found text{display:block;font-weight:400;font-size:23rpx;color:#839485;margin:20rpx}.not-found button{width:260rpx;background:#254d36;color:#fff;font-size:24rpx}.side-card{background:#173c2c;color:#f1f7e9;border-radius:12rpx;padding:28rpx}.side-eyebrow{font-size:18rpx;letter-spacing:1rpx;color:#a7ca83}.side-title{font-size:31rpx;font-weight:750;line-height:1.5;margin:20rpx 0}.side-copy{font-size:22rpx;line-h